// MIT. Private merchant drafts and package operations around the original compiler.
import { DatabaseSync } from 'node:sqlite';
import { mkdir, realpath, lstat, chmod } from 'node:fs/promises';
import { resolve } from 'node:path';
import { createHash, randomUUID } from 'node:crypto';

export class WorkspaceError extends Error {
  constructor(code, status = 422, message = code) {
    super(message); this.name = 'WorkspaceError'; this.code = code; this.status = status;
  }
}
export const sha256 = value => createHash('sha256').update(value).digest('hex');
export const json = value => JSON.stringify(value, null, 2) + '\n';
export function operationId(value) {
  if (typeof value !== 'string' || !/^[a-z][a-z0-9-]{7,79}$/.test(value))
    throw new WorkspaceError('OPERATION_ID_REQUIRED');
  return value;
}
export function revisionNumber(value) {
  if (!Number.isSafeInteger(value) || value < 0) throw new WorkspaceError('INVALID_DRAFT_REVISION');
  return value;
}
export function encodePlan(plan) {
  if (!plan || typeof plan !== 'object' || Array.isArray(plan)) throw new WorkspaceError('MERCHANT_PLAN_REQUIRED');
  const text = json(plan);
  if (Buffer.byteLength(text) > 262144) throw new WorkspaceError('MERCHANT_PLAN_TOO_LARGE');
  return text;
}
export function encodeAuthoring(authoring = []) {
  if (!Array.isArray(authoring) || authoring.length > 32 || Buffer.byteLength(json(authoring)) > 131072)
    throw new WorkspaceError('QUERY_AUTHORING_DRAFT_INVALID');
  return json(authoring);
}
const rowDraft = row => row ? { revision: row.revision, operationId: row.operation_id,
  sourceSha256: row.source_sha256, planSha256: row.plan_sha256,
  savedAt: row.saved_at, plan: JSON.parse(row.plan), authoring: JSON.parse(row.authoring ?? '[]') } : null;
const rowPackage = row => row ? { id: row.id, revision: row.revision, state: row.state,
  sourceSha256: row.source_sha256, reviewId: row.review_id, createdAt: row.created_at,
  completedAt: row.completed_at, error: row.error,
  summary: row.summary ? JSON.parse(row.summary) : null } : null;

async function privateDirectory(path) {
  await mkdir(path, { recursive: true, mode: 0o700 });
  if (await realpath(path) !== path || !(await lstat(path)).isDirectory())
    throw new WorkspaceError('PRIVATE_WORKSPACE_DIRECTORY_REQUIRED');
  await chmod(path, 0o700);
}
async function regularOrMissing(path) {
  try {
    const file = await lstat(path);
    if (!file.isFile() || file.isSymbolicLink()) throw new WorkspaceError('WORKSPACE_FILE_INVALID');
    return file;
  } catch (error) { if (error.code !== 'ENOENT') throw error; }
  return null;
}

/** Read the retained selection before the normal workspace acquires its ownership lock. */
export async function readSavedWorkspaceSource(directory) {
  const root = resolve(directory), filename = resolve(root, 'workspace.sqlite');
  if (await realpath(root) !== root || !(await lstat(root)).isDirectory())
    throw new WorkspaceError('PRIVATE_WORKSPACE_DIRECTORY_REQUIRED');
  if (!await regularOrMissing(filename)) throw new WorkspaceError('SAVED_WORKSPACE_SOURCE_REQUIRED', 404);
  let db;
  try {
    db = new DatabaseSync(filename, { readOnly: true });
    const source = db.prepare('SELECT value FROM metadata WHERE key=?').get('sourceFile')?.value;
    if (typeof source !== 'string' || !source || resolve(source) !== source || source.includes('\0'))
      throw new WorkspaceError('SAVED_WORKSPACE_SOURCE_REQUIRED', 404);
    return source;
  } finally { db?.close(); }
}

/** A native SQLite lock is released by the OS after a crash, without PID guessing. */
export async function openWorkspaceStore({ directory, sourceFile }) {
  const root = resolve(directory), canonicalSource = await realpath(resolve(sourceFile)).catch(error => {
    if (error.code === 'ENOENT') return resolve(sourceFile);
    throw error;
  });
  await privateDirectory(root);
  for (const name of ['inputs', 'packages']) await privateDirectory(resolve(root, name));
  const ownerPath = resolve(root, 'runtime-lock.sqlite'), dataPath = resolve(root, 'workspace.sqlite');
  await regularOrMissing(ownerPath); await regularOrMissing(dataPath);
  let owner, db, closed = false;
  try {
    owner = new DatabaseSync(ownerPath);
    owner.exec('PRAGMA busy_timeout=0; BEGIN EXCLUSIVE;');
    await chmod(ownerPath, 0o600);
    db = new DatabaseSync(dataPath);
    await chmod(dataPath, 0o600);
    db.exec(`PRAGMA busy_timeout=1000; PRAGMA foreign_keys=ON; PRAGMA synchronous=FULL;
      CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS drafts (
        revision INTEGER PRIMARY KEY, operation_id TEXT NOT NULL UNIQUE,
        source_sha256 TEXT NOT NULL, plan_sha256 TEXT NOT NULL, plan TEXT NOT NULL, saved_at TEXT NOT NULL
      );
      CREATE TABLE IF NOT EXISTS packages (
        id TEXT PRIMARY KEY, revision INTEGER NOT NULL REFERENCES drafts(revision),
        review_id TEXT NOT NULL, source_sha256 TEXT NOT NULL,
        state TEXT NOT NULL, created_at TEXT NOT NULL, completed_at TEXT, error TEXT, summary TEXT
      );
      CREATE TABLE IF NOT EXISTS runtime (id INTEGER PRIMARY KEY CHECK (id=1), body TEXT NOT NULL);`);
    const existing = db.prepare('SELECT value FROM metadata WHERE key=?').get('sourceFile');
    if (existing && existing.value !== canonicalSource) throw new WorkspaceError('WORKSPACE_SOURCE_MISMATCH', 409);
    db.prepare('INSERT OR IGNORE INTO metadata(key,value) VALUES (?,?)').run('sourceFile', canonicalSource);
    db.prepare('INSERT OR IGNORE INTO metadata(key,value) VALUES (?,?)').run('workspaceId', randomUUID());
    if (!db.prepare('PRAGMA table_info(drafts)').all().some(column => column.name === 'authoring'))
      db.exec("ALTER TABLE drafts ADD COLUMN authoring TEXT NOT NULL DEFAULT '[]'");
    db.exec("UPDATE packages SET state='INTERRUPTED' WHERE state='PREPARING'");
    const prior = db.prepare('SELECT body FROM runtime WHERE id=1').get();
    if (prior) {
      const value = JSON.parse(prior.body);
      if (['STARTING', 'RUNNING', 'STOPPING'].includes(value.state)) {
        value.state = 'INTERRUPTED'; value.endedAt = new Date().toISOString();
        db.prepare('UPDATE runtime SET body=? WHERE id=1').run(json(value));
      }
    }
  } catch (error) {
    try { db?.close(); } catch {}
    try { owner?.close(); } catch {}
    if (error?.errcode === 5 || /database is locked/i.test(error?.message ?? ''))
      throw new WorkspaceError('WORKSPACE_ALREADY_OPEN', 409, 'This workspace is already open in another process.');
    throw error;
  }
  function transaction(fn) {
    db.exec('BEGIN IMMEDIATE');
    try { const result = fn(); db.exec('COMMIT'); return result; }
    catch (error) { db.exec('ROLLBACK'); throw error; }
  }
  const latest = () => rowDraft(db.prepare('SELECT * FROM drafts ORDER BY revision DESC LIMIT 1').get());
  const getDraft = revision => rowDraft(db.prepare('SELECT * FROM drafts WHERE revision=?').get(revisionNumber(revision)));
  const getPackage = id => rowPackage(db.prepare('SELECT * FROM packages WHERE id=?').get(operationId(id)));
  return {
    directory: root, latest, getDraft, getPackage,
    get sourceFile() { return db.prepare('SELECT value FROM metadata WHERE key=?').get('sourceFile').value; },
    extension(initialize) { return initialize({ db, transaction }); },
    selectSourceFile(value, expected) {
      if (typeof value !== 'string' || resolve(value) !== value || value.includes('\0'))
        throw new WorkspaceError('CLOUD_SOURCE_PATH_INVALID');
      const current = db.prepare('SELECT value FROM metadata WHERE key=?').get('sourceFile').value;
      if (current !== expected && current !== value) throw new WorkspaceError('SOURCE_CHANGED', 409);
      db.prepare('UPDATE metadata SET value=? WHERE key=?').run(value, 'sourceFile');
      return value;
    },
    workspaceId: db.prepare('SELECT value FROM metadata WHERE key=?').get('workspaceId').value,
    sourceDescription(value) {
      if (value !== undefined) db.prepare('INSERT INTO metadata(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value')
        .run('sourceDescription', json(value));
      const row = db.prepare('SELECT value FROM metadata WHERE key=?').get('sourceDescription');
      return row ? JSON.parse(row.value) : null;
    },
    drafts() {
      return db.prepare('SELECT revision,source_sha256,plan_sha256,saved_at FROM drafts ORDER BY revision DESC LIMIT 100').all()
        .map(row => ({ revision: row.revision, sourceSha256: row.source_sha256,
          planSha256: row.plan_sha256, savedAt: row.saved_at }));
    },
    saveDraft({ expectedRevision, operationId: id, sourceSha256, plan, authoring = [] }) {
      revisionNumber(expectedRevision); operationId(id);
      const bytes = encodePlan(plan), hash = sha256(bytes), authors = encodeAuthoring(authoring);
      if (Buffer.byteLength(bytes) + Buffer.byteLength(authors) > 262144)
        throw new WorkspaceError('MERCHANT_DRAFT_TOO_LARGE');
      return transaction(() => {
        const repeat = rowDraft(db.prepare('SELECT * FROM drafts WHERE operation_id=?').get(id));
        if (repeat) {
          if (repeat.planSha256 !== hash || repeat.sourceSha256 !== sourceSha256 || json(repeat.authoring) !== authors)
            throw new WorkspaceError('OPERATION_CONTENT_CONFLICT', 409);
          return repeat;
        }
        const current = latest()?.revision ?? 0;
        if (current !== expectedRevision) throw new WorkspaceError('DRAFT_REVISION_CHANGED', 409,
          'Another save changed the current draft. Reopen it before saving your edits.');
        const revision = current + 1;
        db.prepare('INSERT INTO drafts(revision,operation_id,source_sha256,plan_sha256,plan,saved_at,authoring) VALUES (?,?,?,?,?,?,?)')
          .run(revision, id, sourceSha256, hash, bytes, new Date().toISOString(), authors);
        return getDraft(revision);
      });
    },
    beginPackage({ id, revision, reviewId, sourceSha256 }) {
      operationId(id); revisionNumber(revision);
      return transaction(() => {
        const repeat = getPackage(id);
        if (repeat) {
          if (repeat.revision !== revision || repeat.reviewId !== reviewId || repeat.sourceSha256 !== sourceSha256)
            throw new WorkspaceError('OPERATION_CONTENT_CONFLICT', 409);
          return { existing: true, package: repeat };
        }
        db.prepare('INSERT INTO packages(id,revision,review_id,source_sha256,state,created_at) VALUES (?,?,?,?,?,?)')
          .run(id, revision, reviewId, sourceSha256, 'PREPARING', new Date().toISOString());
        return { existing: false, package: getPackage(id) };
      });
    },
    completePackage(id, summary) {
      db.prepare("UPDATE packages SET state='READY', completed_at=?, error=NULL, summary=? WHERE id=?")
        .run(new Date().toISOString(), json(summary), operationId(id));
      return getPackage(id);
    },
    failPackage(id, code) {
      db.prepare("UPDATE packages SET state='INCOMPLETE', error=? WHERE id=?").run(code, operationId(id));
      return getPackage(id);
    },
    packages() { return db.prepare('SELECT * FROM packages ORDER BY created_at DESC LIMIT 100').all().map(rowPackage); },
    runtime() {
      const row = db.prepare('SELECT body FROM runtime WHERE id=1').get();
      return row ? JSON.parse(row.body) : { state: 'STOPPED', instanceId: null, packageId: null };
    },
    setRuntime(value) {
      db.prepare('INSERT INTO runtime(id,body) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET body=excluded.body').run(json(value));
      return value;
    },
    close() {
      if (closed) return;
      closed = true;
      try { db.close(); } finally { owner.close(); }
    },
  };
}

// MIT. Retained feed operator and original merchant/buyer entry points.
import { spawn } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { resolve, isAbsolute } from 'node:path';

export async function main(input = process.argv.slice(2)) {
  let python = process.env.SF30_FEED_PYTHON || process.env.SF30_XML_PYTHON || 'python3';
  if (input[0] === '--python') {
    if (typeof input[1] !== 'string' || !isAbsolute(input[1]) || input[1].includes('\0'))
      throw new TypeError('Choose an absolute existing Python executable');
    python = input[1]; input = input.slice(2);
  }
  if (input[0] === 'merchant' || input[0] === 'buyer')
    return (await import('./merchant.mjs')).main(input);
  if (!input.length || input.length === 1 && input[0] === '--help') {
    process.stdout.write('RSS 2.0 / Atom 1.0 retained feeds\n\n' +
      '  feeds [--python EXECUTABLE] --workspace DIR init|serve|binding|subscriptions|register|capture|review|apply|records|edition|query|compare|export|project|receive\n' +
      '  feeds merchant --help     Prepare the original SF82 dataset release\n' +
      '  feeds buyer --help        Review the live original offer and prepare SF88 acquisition\n\n' +
      'Python 3.11+ and Node 22+; feed capture and native datasets use the standard library.\n\n');
    input = ['--help'];
  }
  const child = spawn(python,
    [fileURLToPath(new URL('./cli.py', import.meta.url)), ...input], {
      stdio: 'inherit', env: { ...process.env, SF30_XML_NODE: process.execPath },
    });
  const handlers = new Map(['SIGINT', 'SIGTERM'].map(signal => [signal, () => child.kill(signal)]));
  for (const [signal, handler] of handlers) process.on(signal, handler);
  try {
    const code = await new Promise((done, reject) => {
      child.once('error', reject);
      child.once('close', (status, signal) => done(status ?? (signal === 'SIGINT' ? 130 : signal === 'SIGTERM' ? 143 : 1)));
    });
    if (code) process.exitCode = code;
    return code;
  } finally { for (const [signal, handler] of handlers) process.removeListener(signal, handler); }
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href)
  main().catch(error => { process.stderr.write('Feeds: ' + error.message + '\n'); process.exitCode = 1; });

// MIT. Retained feed editions in the original SF82 release and SF88 buyer lifecycle.
import { constants } from 'node:fs';
import { open, mkdir, realpath, lstat, unlink } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { basename, dirname, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { isDeepStrictEqual } from 'node:util';
import { loadDatasetConfig } from '../dataset-handler.mjs';
import { buildDatasetSellerConfig } from '../dataset-cli.mjs';
import { openDatasetVersions, DATASET_SNAPSHOT_PARAMETER } from '../dataset-refresh/versions.mjs';
import { DATASET_BINDING_SCHEMA, datasetContractSha256, prepareDatasetRelease,
  stageDatasetRelease, inspectDatasetRelease, startDatasetRelease } from '../../sf82-seller-pilot/release-dataset.mjs';
import { readDatasetBuyerOffer, prepareDatasetBuyer } from '../dataset-refresh/buyer-handoff.mjs';

const MiB = 1024 * 1024;
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const encode = value => Buffer.from(JSON.stringify(value, null, 2) + '\n');
const parse = bytes => JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
const canonical = value => Array.isArray(value) ? value.map(canonical) : value && typeof value === 'object'
  ? Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])])) : value;
const fingerprint = value => hash(encode(canonical(value)));
const fail = message => { throw new TypeError(message); };
async function present(path) {
  try { await lstat(path); return true; } catch (error) { if (error.code === 'ENOENT') return false; throw error; }
}
async function read(path, maximum = MiB) {
  path = resolve(path);
  if (await realpath(path) !== path) fail('Use canonical source files without symlinks.');
  const file = await open(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
  try {
    const before = await file.stat({ bigint: true });
    if (!before.isFile() || before.size > BigInt(maximum)) fail('Source file exceeds its supported size.');
    const bytes = await file.readFile(), after = await file.stat({ bigint: true });
    if (BigInt(bytes.length) !== before.size || before.size !== after.size || before.mtimeNs !== after.mtimeNs ||
        before.ctimeNs !== after.ctimeNs) fail('Source file changed during capture.');
    return bytes;
  } finally { await file.close(); }
}
async function targetDirectory(path) {
  const target = resolve(path);
  if (join(await realpath(dirname(target)), basename(target)) !== target) fail('Use an existing canonical parent directory.');
  try { await mkdir(target, { mode: 0o700 }); }
  catch (error) { if (error.code !== 'EEXIST') throw error; }
  const info = await lstat(target);
  if (!info.isDirectory() || await realpath(target) !== target ||
      process.platform !== 'win32' && (info.uid !== process.getuid() || (info.mode & 0o077)))
    fail('Use private operator-owned directories (mode 0700).');
  return target;
}
async function exactFile(path, bytes) {
  let file;
  try { file = await open(path, 'wx', 0o600); }
  catch (error) {
    if (error.code !== 'EEXIST') throw error;
    if (!(await read(path, bytes.length)).equals(bytes)) fail('The retained output differs; select a new output directory.');
    return;
  }
  const owned = await file.stat({ bigint:true });
  try { await file.writeFile(bytes); await file.sync(); }
  catch (error) {
    try {
      const current = await lstat(path, { bigint:true });
      if (current.dev === owned.dev && current.ino === owned.ino) await unlink(path);
    } catch (cleanupError) { if (cleanupError.code !== 'ENOENT') error.cleanup = cleanupError.message; }
    throw error;
  } finally { await file.close(); }
}
const descriptor = (path, bytes) => ({ path, bytes: bytes.length, sha256: hash(bytes) });

async function readFeedDataset(input) {
  if (await realpath(input) !== input) fail('Use the canonical feed export directory.');
  const originalConfig = await read(join(input, 'dataset.json'));
  const config = parse(originalConfig);
  if (config.file !== 'data.csv') fail('Choose the original feed workspace dataset export.');
  const csv = await read(join(input, 'data.csv'), 256 * MiB);
  const feedBytes = await read(join(input, 'feed-lineage.json'), 256 * MiB);
  const xmlBytes = await read(join(input, 'xml-lineage.json'), 2 * MiB);
  const lineage = parse(feedBytes), xml = parse(xmlBytes);
  if (lineage.schema !== 'stellar-forge.feed-dataset-lineage.v1' ||
      !/^[a-f0-9]{64}$/.test(lineage.editionId ?? '') || lineage.buildId !== xml.id ||
      xml.files?.['data.csv']?.sha256 !== hash(csv) ||
      xml.files?.['dataset.json']?.sha256 !== hash(originalConfig))
    fail('The original feed edition, XML build and dataset export differ.');
  const dataset = await loadDatasetConfig(join(input, 'dataset.json')), description = dataset.describe();
  if (description.rowCount !== lineage.rowCount || !isDeepStrictEqual(description.columns.map(c => c.name), lineage.fields))
    fail('The native dataset differs from the selected feed projection.');
  return { originalConfig, config, csv, feedBytes, xmlBytes, lineage, xml, dataset, description };
}

/** The same verified feed edition as a source package for the maintained publisher.
 * This opens no version writer or listener. The caller retains this exact private
 * directory; original native source-file closure and package checks still apply. */
export async function prepareFeedPublisherPackage({ datasetExport, packageDirectory, payment, origin, path = '/feed' } = {}) {
  const input = resolve(datasetExport), out = resolve(packageDirectory);
  if (input === out) fail('Use separate original dataset and merchant package directories.');
  const { originalConfig, config, csv, feedBytes, xmlBytes, lineage, xml, dataset, description } = await readFeedDataset(input);
  const seller = await buildDatasetSellerConfig(dataset, { payment, origin, path });
  if (seller.routes[0].definition.queryParameters.length >= 32) fail('The original snapshot selector needs a native query slot.');
  seller.routes[0].definition.queryParameters.push({ ...DATASET_SNAPSHOT_PARAMETER });
  const request = { schema:'stellar-forge.feed-publisher-package-request.v1', datasetExport:input, packageDirectory:out,
    editionId:lineage.editionId, csvSha256:hash(csv), configSha256:hash(originalConfig),
    feedLineageSha256:hash(feedBytes), xmlLineageSha256:hash(xmlBytes), payment, origin, path };
  await targetDirectory(out);
  await exactFile(join(out, 'feed-package-request.json'), encode({ ...request, requestSha256:fingerprint(request) }));
  await exactFile(join(out, 'dataset.csv'), csv);
  await exactFile(join(out, 'dataset.json'), encode({ ...config, file:'dataset.csv' }));
  await exactFile(join(out, 'seller.json'), encode(seller));
  await targetDirectory(join(out, 'provenance'));
  await exactFile(join(out, 'provenance', 'feed-lineage.json'), feedBytes);
  await exactFile(join(out, 'provenance', 'xml-lineage.json'), xmlBytes);
  const source = { schema:'stellar-forge.feed-merchant-source.v1', editionId:lineage.editionId, buildId:lineage.buildId,
    normalizedXmlSha256:xml.source, fields:lineage.fields, feedRevisions:lineage.revisions, rowCount:lineage.rowCount,
    sourceFiles:[descriptor('provenance/feed-lineage.json', feedBytes), descriptor('provenance/xml-lineage.json', xmlBytes)] };
  await exactFile(join(out, 'source.json'), encode(source));
  if (!(await read(join(input, 'dataset.json'))).equals(originalConfig) ||
      !(await read(join(input, 'data.csv'), 256 * MiB)).equals(csv))
    fail('The original dataset export changed during preparation.');
  return { schema:'stellar-forge.feed-publisher-package.v1', editionId:lineage.editionId, buildId:lineage.buildId,
    snapshot:description.snapshot, rowCount:description.rowCount, packageDirectory:out,
    resource:seller.publicOrigin + path, sourceFiles:source.sourceFiles, requestSha256:fingerprint(request) };
}

/** Exact feed export -> native dataset -> native version store -> original release.
 * The selected source package can be retried unchanged after an interrupted reply. */
export async function prepareFeedMerchant({ datasetExport, versionDirectory, packageDirectory, releaseDirectory,
  payment, origin, path = '/feed', retentionMs = 3600000, maxVersions = 4,
  maxRetainedBytes = 256 * MiB } = {}) {
  const input = resolve(datasetExport), out = resolve(packageDirectory), versionsPath = resolve(versionDirectory),
    releasePath = resolve(releaseDirectory);
  if (new Set([input, out, versionsPath, releasePath]).size !== 4)
    fail('Use separate export, package, version-store and release directories.');
  const { originalConfig, config, csv, feedBytes, xmlBytes, lineage, xml, dataset, description } = await readFeedDataset(input);
  const seller = await buildDatasetSellerConfig(dataset, { payment, origin, path });
  if (seller.routes[0].definition.queryParameters.length >= 32) fail('The original snapshot selector needs a native query slot.');
  seller.routes[0].definition.queryParameters.push({ ...DATASET_SNAPSHOT_PARAMETER });
  const request = { schema:'stellar-forge.feed-merchant-request.v1', datasetExport:input, versionDirectory:versionsPath,
    packageDirectory:out, releaseDirectory:releasePath, editionId:lineage.editionId,
    csvSha256:hash(csv), configSha256:hash(originalConfig), feedLineageSha256:hash(feedBytes),
    xmlLineageSha256:hash(xmlBytes), payment, origin, path, retentionMs, maxVersions, maxRetainedBytes };
  await targetDirectory(out);
  await exactFile(join(out, 'feed-request.json'), encode({ ...request, requestSha256:fingerprint(request) }));
  await exactFile(join(out, 'dataset.csv'), csv);
  await exactFile(join(out, 'dataset.json'), encode({ ...config, file:'dataset.csv' }));
  await exactFile(join(out, 'seller.json'), encode(seller));
  await targetDirectory(join(out, 'provenance'));
  await exactFile(join(out, 'provenance', 'feed-lineage.json'), feedBytes);
  await exactFile(join(out, 'provenance', 'xml-lineage.json'), xmlBytes);
  const source = { schema:'stellar-forge.feed-merchant-source.v1', editionId:lineage.editionId, buildId:lineage.buildId,
    normalizedXmlSha256:xml.source, fields:lineage.fields, feedRevisions:lineage.revisions, rowCount:lineage.rowCount,
    sourceFiles:[descriptor('provenance/feed-lineage.json', feedBytes), descriptor('provenance/xml-lineage.json', xmlBytes)] };
  const sourceBytes = encode(source);
  await exactFile(join(out, 'source.json'), sourceBytes);
  await exactFile(join(out, 'binding.json'), encode({ schema:DATASET_BINDING_SCHEMA, datasetDirectory:versionsPath,
    contractSha256:datasetContractSha256(description), baselineSnapshot:description.snapshot, sourceSha256:hash(sourceBytes) }));
  const prepared = await prepareDatasetRelease(out);
  if (prepared.description.snapshot !== description.snapshot) fail('The original release changed the selected dataset snapshot.');
  // Input bytes are rechecked before the version writer is opened.
  if (!(await read(join(input, 'dataset.json'))).equals(originalConfig) ||
      !(await read(join(input, 'data.csv'), 256 * MiB)).equals(csv))
    fail('The original dataset export changed during preparation.');
  const existing = await present(join(versionsPath, 'state.json'));
  await targetDirectory(versionsPath);
  const versions = await openDatasetVersions({ directory:versionsPath, ...(existing ? {} :
    { initialConfig:join(out, 'dataset.json'), retentionMs, maxVersions, maxRetainedBytes }) });
  let status;
  try {
    status = versions.status();
    if (status.current !== description.snapshot || datasetContractSha256(versions.describe()) !== prepared.binding.contractSha256)
      fail('This version store currently serves another edition. Select a new store, or use the original guarded dataset refresh command.');
  } finally { await versions.close(); }
  let staged;
  if (await present(releasePath)) {
    staged = await inspectDatasetRelease(releasePath);
    if (!isDeepStrictEqual(staged.manifest.dataset, prepared.dataset) || !isDeepStrictEqual(staged.manifest.files, prepared.files))
      fail('The selected original release directory contains another source package.');
  } else {
    staged = await stageDatasetRelease(releasePath, out);
  }
  const result = { schema:'stellar-forge.feed-merchant-release.v1', editionId:lineage.editionId, buildId:lineage.buildId,
    snapshot:description.snapshot, rowCount:description.rowCount, versionDirectory:versionsPath,
    packageDirectory:out, releaseDirectory:releasePath, resource:seller.publicOrigin + path,
    offersSha256:staged.manifest.offersSha256, serviceConfigSha256:staged.manifest.serviceConfigSha256,
    sourceClosure:staged.manifest.dataset.sourceClosure, revision:status.revision, requestSha256:fingerprint(request) };
  await exactFile(join(out, 'feed-release.json'), encode(result));
  return result;
}

