#!/usr/bin/env node
// MIT. Source-package operations and the original local publisher in one command.
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { main as publisherMain } from '../postgres/publisher/cli.mjs';
import { bytes, createFile, readJson, fault } from '../postgres/publisher/files.mjs';
import { openFrictionlessPublisher } from './model.mjs';
import { inspectFrictionlessSource, runFrictionlessCommand } from './source.mjs';

const SOURCE_COMMANDS = new Set(['capture', 'inspect-capture', 'suggest-source', 'source-export', 'source-receive', 'compare', 'review-source']);
const HELP = `Frictionless Data Package merchant publisher

Source edition:
  capture --descriptor PATH_OR_HTTPS_URL --output NEW_DIR [--resource NAME ...]
          [--reference PATH_OR_HTTPS_URL ...]
  inspect-capture --capture CAPTURE.json [--sha256 HASH]
  suggest-source --capture CAPTURE.json --output SOURCE.json
  review-source --source REVIEWED_SOURCE.json
  plan --source REVIEWED_SOURCE.json --query NAME --out PLAN.json
  source-export --source SOURCE.json --output PACKAGE.tar.gz
  source-receive --archive PACKAGE.tar.gz --sha256 HASH --output NEW_DIR
  compare --before OLD_CAPTURE.json --after NEW_CAPTURE.json

Original SF82 release:
  release-prepare --workspace DIR --run UUID --output NEW_PACKAGE_DIR
                  --payment PAYMENT.json --origin HTTPS_ORIGIN [--path /data]
  release-stage --package PACKAGE_DIR --releases RELEASE_STORE --id ID
                [--label TEXT] [--runtime RUNTIME.json]
  Activate, compare, roll back and run with sf82-seller-pilot/release-cli.mjs.

Publisher (same maintained source publisher and browser):
  init --workspace NEW_DIR --source REVIEWED_SOURCE.json --state DATASET_DIR
  save --workspace DIR --input REVIEWED_PLAN.json
  extract --workspace DIR --plan NUMBER
  inspect --workspace DIR --run UUID [--query 'limit=20']
  review --workspace DIR --run UUID --reviewer NAME --note TEXT --initialize
  publish --workspace DIR --run UUID --review REVIEW_ID
  serve --workspace DIR [--port 8487]
  status --workspace DIR
  buyer --workspace DIR --run UUID --seller LOCAL_ORIGIN --resource HTTPS_RESOURCE
  schedule, schedule-save, schedule-enable, schedule-pause, schedule-run,
  schedule-continue, recover: use the maintained publisher arguments.

Python 3.10+, Node 22.16+, util-linux flock. SF_FRICTIONLESS_PYTHON selects an
installed Python executable. No additional Python dependencies are required.
Source suggestions retain physical strings and literal missing markers. Review
the source projection, then use plan to carry its exact types into the original
native CSV schema. The saved plan keeps the full original package capture.
See README.md for refresh, original SF82 release and SF88/SF100 receiving.
`;

function options(args, keys, required = keys) {
  const result = {};
  for (let i = 0; i < args.length; i++) {
    if (!keys.includes(args[i]) || Object.hasOwn(result, args[i]) || !args[i + 1] || args[i + 1].startsWith('--'))
      throw fault('PACKAGE_OPTION_INVALID', args[i]);
    result[args[i]] = args[++i];
  }
  if (required.some(key => !result[key])) throw fault('PACKAGE_OPTION_REQUIRED', required.join(', '));
  return result;
}

export async function makeFrictionlessPlan(sourceFile, queryName, output) {
  const source = await inspectFrictionlessSource(resolve(sourceFile)), query = source.queries[queryName];
  if (!query) throw fault('QUERY_NOT_FOUND');
  const columns = Object.fromEntries(Object.entries(query.projection).map(([alias, spec]) =>
    [alias, { type: spec.type, nullable: spec.missing === 'null' }]));
  const plan = { title: queryName + ' retained package edition', query: queryName, input: {}, sourceHash: source.hash,
    dataset: { name: queryName, columns, filters: [], ranges: [], sorts: [], defaultLimit: 50, maxLimit: 250,
      maxCellChars: 65536, maxPageBytes: 921600 },
    extraction: { order: [{ column: query.columns[0], direction: 'asc' }], maxRows: 250000,
      maxBytes: 67108864, maxRowBytes: 1048576, timeoutMs: 300000 } };
  await createFile(resolve(output), bytes(plan));
  return { created: resolve(output), sourceHash: source.hash, resource: query.resource, columns,
    captureSha256: source.captureSha256 };
}

export async function main(argv = process.argv.slice(2)) {
  if (!argv.length || argv[0] === '--help') { process.stdout.write(HELP); return; }
  if (SOURCE_COMMANDS.has(argv[0])) return runFrictionlessCommand(argv);
  if (argv[0] === 'plan') {
    const input = options(argv.slice(1), ['--source', '--query', '--out']);
    const result = await makeFrictionlessPlan(input['--source'], input['--query'], input['--out']);
    process.stdout.write(JSON.stringify(result, null, 2) + '\n'); return result;
  }
  if (argv[0] === 'release-prepare') {
    const required = ['--workspace', '--run', '--output', '--payment', '--origin'];
    const input = options(argv.slice(1), [...required, '--path'], required);
    const payment = await readJson(resolve(input['--payment']), 16384);
    const { prepareFrictionlessRelease } = await import('./release.mjs');
    const publisher = await openFrictionlessPublisher({ directory: resolve(input['--workspace']) });
    try {
      const result = await prepareFrictionlessRelease({ publisher, runId: input['--run'],
        outputDirectory: resolve(input['--output']), payment, origin: input['--origin'],
        path: input['--path'] ?? '/data' });
      process.stdout.write(JSON.stringify(result, null, 2) + '\n'); return result;
    } finally { await publisher.close(); }
  }
  if (argv[0] === 'release-stage') {
    const required = ['--package', '--releases', '--id'];
    const input = options(argv.slice(1), [...required, '--label', '--runtime'], required);
    const runtime = input['--runtime'] ? await readJson(resolve(input['--runtime']), 16384) : { port: 0 };
    const { stageFrictionlessRelease } = await import('./release.mjs');
    const result = await stageFrictionlessRelease({ packageDirectory: resolve(input['--package']),
      releaseDirectory: resolve(input['--releases']), id: input['--id'],
      label: input['--label'] ?? input['--id'], runtime });
    process.stdout.write(JSON.stringify(result, null, 2) + '\n'); return result;
  }
  return publisherMain(argv, { openPublisher: openFrictionlessPublisher, sourceName: 'Frictionless Data Package', defaultPort: 8487 });
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href)
  main().catch(issue => {
    process.stderr.write((issue.code ?? 'PACKAGE') + ': ' + (issue.code ? issue.message : 'Inspect the source and selected operator inputs.') + '\n');
    process.exitCode = 1;
  });

// MIT. Frictionless source retention in the original durable dataset publisher.
import { dirname, join, posix } from 'node:path';
import { loadCsvDataset } from '../dataset-handler.mjs';
import { csvLine } from '../postgres/publisher/plan.mjs';
import { datasetExtractionOptions } from '../postgres/publisher/stream.mjs';
import { object, bytes, digest, identity, readPrivate, createFile, privateDirectory, syncDirectory, fault } from '../postgres/publisher/files.mjs';
import { inspectFrictionlessSource, openFrictionlessSourceFile, checkFrictionlessColumnTypes, encodeFrictionlessRow } from './source.mjs';

const HASH = /^[a-f0-9]{64}$/;
const only = (value, keys, code) => {
  if (!object(value) || Object.keys(value).some(key => !keys.includes(key))) throw fault(code);
};
function captureMember(name) {
  if (typeof name !== 'string' || !name || name.length > 1024 || name.includes('\\') || name.includes('\0') ||
      posix.isAbsolute(name) || posix.normalize(name) !== name || name.split('/').some(v => !v || v === '.' || v === '..') ||
      name === 'capture.json') throw fault('PACKAGE_CAPTURE_MEMBER_INVALID');
  return name;
}
async function retainCapture(selected, target) {
  const manifest = selected.capture;
  if (manifest?.schema !== 'stellar-forge.frictionless-capture.v1' || manifest.state !== 'COMPLETE' ||
      !Array.isArray(manifest.files) || !manifest.files.length || manifest.files.length > 10000)
    throw fault('PACKAGE_CAPTURE_INVALID');
  const original = await readPrivate(selected.captureFile, 8388608);
  if (digest(original) !== selected.captureSha256) throw fault('PACKAGE_CAPTURE_CHANGED');
  await privateDirectory(target, true);
  const names = new Set();
  for (const item of manifest.files) {
    const name = captureMember(item.file);
    if (names.has(name) || !HASH.test(item.sha256 ?? '') || !Number.isSafeInteger(item.bytes) || item.bytes < 0 ||
        item.bytes > 268435456) throw fault('PACKAGE_CAPTURE_FILES_INVALID');
    names.add(name);
    const content = await readPrivate(join(dirname(selected.captureFile), name), 268435456);
    if (digest(content) !== item.sha256 || content.length !== item.bytes) throw fault('PACKAGE_CAPTURE_MEMBER_CHANGED');
    await privateDirectory(dirname(join(target, name)), true);
    await createFile(join(target, name), content);
  }
  await createFile(join(target, 'capture.json'), original);
  await syncDirectory(join(target, 'files')); await syncDirectory(target);
}

export async function captureFrictionlessPlan(sourceFile, directory, input) {
  only(input, ['title', 'query', 'input', 'dataset', 'extraction', 'sourceHash'], 'INVALID_PUBLICATION_PLAN');
  if (typeof input.title !== 'string' || !input.title.trim() || input.title.length > 128) throw fault('PLAN_TITLE_REQUIRED');
  const selected = await inspectFrictionlessSource(sourceFile);
  const original = await readPrivate(sourceFile, 8388608);
  if (digest(original) !== selected.hash || selected.hash !== input.sourceHash)
    throw fault('SOURCE_REVIEW_CHANGED', 'Reload the Frictionless source before saving this plan.', 409);
  const query = selected.queries[input.query];
  if (!query) throw fault('QUERY_NOT_FOUND');
  if (!object(input.input ?? {}) || Object.keys(input.input ?? {}).length) throw fault('PACKAGE_QUERY_INPUT_NOT_SUPPORTED');
  const extraction = datasetExtractionOptions(query, input.extraction);
  only(input.dataset, ['name', 'columns', 'filters', 'ranges', 'sorts', 'maxCellChars', 'defaultLimit', 'maxLimit', 'maxPageBytes'], 'INVALID_DATASET_PLAN');
  if (!object(input.dataset.columns) || !Object.keys(input.dataset.columns).length ||
      Object.keys(input.dataset.columns).some(name => !query.columns.includes(name))) throw fault('DATASET_COLUMN_NOT_IN_QUERY');
  const columns = Object.fromEntries(Object.entries(input.dataset.columns).map(([name, spec]) => {
    const value = typeof spec === 'string' ? { type: spec, nullable: false } : spec;
    only(value, ['type', 'nullable'], 'INVALID_DATASET_COLUMN');
    return [name, { type: value.type, nullable: value.nullable ?? false }];
  }));
  const types = Object.entries(query.projection).map(([name, spec]) => ({
    name, type: spec.type, nullable: spec.missing === 'null',
  }));
  checkFrictionlessColumnTypes(columns, types);
  const dataset = { schema: 'stellar-forge.csv-dataset.v1', file: 'data.csv', name: input.dataset.name,
    columns, filters: input.dataset.filters ?? [], ranges: input.dataset.ranges ?? [], sorts: input.dataset.sorts ?? [],
    maxBytes: extraction.maxBytes, maxRows: extraction.maxRows, maxCellChars: input.dataset.maxCellChars ?? 65536,
    defaultLimit: input.dataset.defaultLimit ?? 50, maxLimit: input.dataset.maxLimit ?? 250,
    maxPageBytes: input.dataset.maxPageBytes ?? 921600 };
  await createFile(join(directory, 'schema.csv'), csvLine(Object.keys(columns)));
  await loadCsvDataset({ ...dataset, file: join(directory, 'schema.csv') });
  await retainCapture(selected, join(directory, 'capture'));
  const runtime = structuredClone(selected.config);
  runtime.connection.file = 'capture/capture.json';
  const runtimeBytes = bytes(runtime);
  await createFile(join(directory, 'original-source.json'), original);
  await createFile(join(directory, 'source.json'), runtimeBytes);
  const value = { schema: 'stellar-forge.frictionless-dataset-plan.v1', title: input.title.trim(),
    query: input.query, input: {}, dataset, extraction, sourceHash: selected.hash, sourceBytes: original.length,
    runtimeSourceHash: digest(runtimeBytes), queryHash: identity(query),
    retainedCapture: { manifestSha256: selected.captureSha256, resource: query.resource,
      descriptorFile: selected.capture.descriptorFile, origin: selected.capture.origin },
    sourceQuery: { ...query } };
  value.digest = identity(value);
  await createFile(join(directory, 'plan.json'), bytes(value));
  return value;
}

export const frictionlessPublisherDriver = Object.freeze({
